"use strict";
(() => {
  const data = window.PROJECT_DATA;
  const groups = window.COMPARISON_GROUPS || [];
  if (!data) return;
  const byId = id => document.getElementById(id);
  const sceneSelect = byId('scene-select');
  sceneSelect.replaceChildren(...data.scenes.map((scene, i) => new Option(scene.name.replaceAll('_', ' '), String(i))));
  const updateMetrics = scene => {
    const ours = data.rows.find(row => row.scene === scene.name && row.method === 'Tortho-Gaussian++');
    const baseline = data.rows.find(row => row.scene === scene.name && row.method === '3DGS');
    const gain = ours.psnr - baseline.psnr;
    byId('psnr-value').textContent = `${gain >= 0 ? '+' : '−'}${Math.abs(gain).toFixed(2)}`;
    byId('psnr-label').textContent = gain >= 0 ? 'PSNR improvement' : 'PSNR change';
    byId('metric-psnr').classList.toggle('metric-increase', gain < 0);
    [['time','Less training time','More training time'], ['vram','Lower peak VRAM','Higher peak VRAM'], ['gaussians','Fewer Gaussians','More Gaussians']].forEach(([key, less, more]) => {
      const reduction = 100 * (1 - ours[key] / baseline[key]);
      byId(`${key}-value`).textContent = Math.abs(reduction).toFixed(1);
      byId(`${key}-label`).textContent = reduction >= 0 ? less : more;
      byId(`metric-${key}`).classList.toggle('metric-increase', reduction < 0);
    });
    byId('metric-note').textContent = `${scene.name.replaceAll('_',' ')} · Tortho-Gaussian++ compared with vanilla 3DGS.`;
  };
  const showScene = () => {
    const scene = data.scenes[Number(sceneSelect.value)];
    const image = byId('scene-image');
    image.src = scene.src;
    image.width = scene.width;
    image.height = scene.height;
    image.alt = `Complete true digital orthophoto map of ${scene.name.replaceAll('_',' ')} generated by Tortho-Gaussian++.`;
    byId('scene-link').href = scene.src;
    byId('scene-link').setAttribute('aria-label', `Open the ${scene.name.replaceAll('_',' ')} orthophoto at full resolution`);
    byId('scene-name').textContent = scene.name.replaceAll('_',' ');
    byId('scene-dataset').textContent = scene.dataset;
    byId('scene-info').textContent = `${scene.images.toLocaleString('en-US')} images · ${scene.views} · ${scene.altitude}`;
    updateMetrics(scene);
  };
  sceneSelect.value = '7';
  showScene();
  sceneSelect.addEventListener('change', showScene);

  const captions = {
    teaser: 'Comparison with Tortho-Gaussian and Ortho-3DGS on SMBU, LOWER, and Residence, illustrating peripheral pruning, drift and floater suppression, and a more reliable projection reference.',
    facades: 'Tilt-induced facade artifacts on low-rise (a) and high-rise (b–d) buildings. The perspective images illustrate the building heights; subsequent rows compare Tortho-Gaussian, Ortho-3DGS, and Tortho-Gaussian++.',
    gravity: 'Challenging acquisition conditions: SMBU and UPPER contain approximately 80% oblique imagery; Residence contains only oblique views with substantial altitude variations. A more reliable projection reference reduces tilt-induced facade artifacts.'
  };
  const tabs = [...document.querySelectorAll('[data-figure]')];
  const groupSelect = byId('group-select');
  const remembered = {drift: 0, floaters: 0};
  let category = 'teaser';
  let activeGroups = [];
  const makeImage = (asset, alt) => {
    const image = document.createElement('img');
    Object.assign(image, {src: asset.src, width: asset.width, height: asset.height, alt, loading: 'lazy', decoding: 'async', draggable: false});
    return image;
  };
  const makeComparison = (group, baseline) => {
    const figure = document.createElement('figure');
    figure.className = 'pair-card';
    const stage = document.createElement('div');
    stage.className = 'pair-stage';
    stage.style.setProperty('--split', '50%');
    stage.append(makeImage(group.ours, `Tortho-Gaussian++: ${category}, ${group.label}.`));
    const overlay = document.createElement('div');
    overlay.className = 'pair-before';
    overlay.append(makeImage(baseline, `${baseline.method}: ${category}, ${group.label}.`));
    stage.append(overlay);
    const divider = document.createElement('span');
    divider.className = 'pair-divider';
    divider.setAttribute('aria-hidden', 'true');
    divider.innerHTML = '<span class="pair-handle">‹<span></span>›</span>';
    stage.append(divider);
    ['before','after'].forEach(side => {
      const label = document.createElement('span');
      label.className = `pair-label label-${side}`;
      label.textContent = side === 'before' ? baseline.method : 'Ours';
      label.setAttribute('aria-hidden', 'true');
      stage.append(label);
    });
    const range = document.createElement('input');
    Object.assign(range, {type: 'range', min: '0', max: '100', step: '1', value: '50', className: 'pair-range'});
    range.setAttribute('aria-label', `${baseline.method} versus Tortho-Gaussian++, ${category}, ${group.label}: comparison position`);
    const update = () => {
      stage.style.setProperty('--split', `${range.value}%`);
      range.setAttribute('aria-valuetext', `${range.value}% ${baseline.method}, ${100 - Number(range.value)}% Tortho-Gaussian++`);
    };
    range.addEventListener('input', update);
    update();
    stage.append(range);
    // Pointer position controls the divider directly; the native range supplies keyboard access.
    const drag = event => {
      const rect = stage.getBoundingClientRect();
      range.value = String(Math.round(Math.min(100, Math.max(0, (event.clientX - rect.left) / rect.width * 100))));
      update();
    };
    stage.addEventListener('pointerdown', event => {
      if (!event.isPrimary || event.button !== 0) return;
      range.focus({preventScroll: true});
      stage.setPointerCapture(event.pointerId);
      drag(event);
    });
    stage.addEventListener('pointermove', event => {
      if (stage.hasPointerCapture(event.pointerId)) drag(event);
    });
    stage.addEventListener('pointerup', event => {
      if (stage.hasPointerCapture(event.pointerId)) stage.releasePointerCapture(event.pointerId);
    });
    const caption = document.createElement('figcaption');
    caption.textContent = `${baseline.method} / Tortho-Gaussian++`;
    figure.append(stage, caption);
    return figure;
  };
  const showGroup = () => {
    const index = Number(groupSelect.value);
    const group = activeGroups[index];
    if (!group) return;
    remembered[category] = index;
    byId('group-count').textContent = `${index + 1} / ${activeGroups.length}`;
    byId('previous-group').disabled = index === 0;
    byId('next-group').disabled = index === activeGroups.length - 1;
    byId('pair-grid').replaceChildren(...group.baselines.map(baseline => makeComparison(group, baseline)));
  };
  groupSelect.addEventListener('change', showGroup);
  byId('previous-group').addEventListener('click', () => { groupSelect.value = String(Number(groupSelect.value) - 1); showGroup(); });
  byId('next-group').addEventListener('click', () => { groupSelect.value = String(Number(groupSelect.value) + 1); showGroup(); });
  const showFigure = button => {
    category = button.dataset.figure;
    tabs.forEach(tab => {
      tab.setAttribute('aria-selected', String(tab === button));
      tab.tabIndex = tab === button ? 0 : -1;
    });
    byId('comparison-panel').setAttribute('aria-labelledby', button.id);
    const paired = category === 'drift' || category === 'floaters';
    byId('pair-browser').hidden = !paired;
    byId('static-comparison').hidden = paired;
    if (paired) {
      activeGroups = groups.filter(group => group.category === category);
      groupSelect.replaceChildren(...activeGroups.map((group, index) => new Option(group.label, String(index))));
      groupSelect.value = String(remembered[category]);
      showGroup();
    } else {
      const figure = data.figures[category];
      const image = byId('comparison-image');
      Object.assign(image, {src: figure.src, width: figure.width, height: figure.height, alt: captions[category]});
      byId('comparison-link').href = figure.src;
      byId('comparison-caption').textContent = captions[category];
      byId('pair-grid').replaceChildren();
    }
  };
  tabs.forEach((button, index) => {
    button.addEventListener('click', () => showFigure(button));
    button.addEventListener('keydown', event => {
      let next;
      if (event.key === 'ArrowRight') next = (index + 1) % tabs.length;
      if (event.key === 'ArrowLeft') next = (index + tabs.length - 1) % tabs.length;
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = tabs.length - 1;
      if (next !== undefined) { event.preventDefault(); tabs[next].focus(); showFigure(tabs[next]); }
    });
  });
  byId('copy-bib').addEventListener('click', async () => {
    const text = byId('bibtex').textContent;
    try {
      if (!navigator.clipboard || !window.isSecureContext) throw new Error('Clipboard unavailable');
      await navigator.clipboard.writeText(text);
      byId('copy-status').textContent = 'BibTeX copied.';
    } catch {
      const selection = window.getSelection();
      const range = document.createRange();
      range.selectNodeContents(byId('bibtex'));
      selection.removeAllRanges(); selection.addRange(range);
      byId('copy-status').textContent = 'BibTeX selected. Press Ctrl+C (or ⌘C) to copy, or download the .bib file.';
    }
  });
})();
